import java.util.List;

/**
 * The policy base premium: the sum of the base premiums of all insured items.
 *
 * The office prices alike items as a group, so that the building-block offer can apply
 * to each group in turn; the policy base premium is the sum of those group prices.
 * Risk surcharges for individual items are not part of it -- they attach to the
 * affected item, not to the policy.
 */
public class PolicyBasePremium {

    private final AlikeItems alikeItems = new AlikeItems();
    private final ComponentBlockOffer blockOffer = new ComponentBlockOffer();

    public double forItems(List<Item> items) {
        double total = 0;
        for (List<Item> group : alikeItems.groupsIn(items)) {
            total += blockOffer.basePremiumFor(group);
        }
        return total;
    }
}
=== PremiumCalculator.java ===
/**
 * Computes the premium for a quote: the policy base premium from the MHPCO price list,
 * the risk surcharges of the individual items, the policy-wide modifiers, and finally
 * the processing fee.
 */
public class PremiumCalculator {

    private static final int PROCESSING_FEE = 5;

    private final PolicyBasePremium policyBasePremiumRule = new PolicyBasePremium();
    private final PolicyRiskSurcharges policyRiskSurcharges = new PolicyRiskSurcharges();
    private final PolicyModifiers policyModifiers = new PolicyModifiers();

    public int premiumFor(QuoteStep quoteStep) {
        double policyBasePremium = policyBasePremiumRule.forItems(quoteStep.items());
        double assessedPremium = policyBasePremium + policyRiskSurcharges.forItems(quoteStep.items());
        double withPolicyModifiers = assessedPremium + policyModifiers.forPolicyBasePremium(policyBasePremium);
        return roundInOfficesFavour(withPolicyModifiers + PROCESSING_FEE);
    }

    private int roundInOfficesFavour(double premium) {
        return (int) Math.ceil(premium);
    }
}
=== PolicyModifiers.java ===
/**
 * The policy-wide modifiers the office applies to a quote.
 *
 * Unlike a risk surcharge, which attaches to the one item that carries the risk, a
 * policy-wide modifier is assessed against the policy base premium -- the sum of all
 * item base premiums. Every quote is a first insurance of its items, so the office
 * charges the initial assessment surcharge on each one.
 */
public class PolicyModifiers {

    private static final double INITIAL_ASSESSMENT_SURCHARGE_RATE = 0.10;

    public double forPolicyBasePremium(double policyBasePremium) {
        return policyBasePremium * INITIAL_ASSESSMENT_SURCHARGE_RATE;
    }
}
